// src/core-mcp/utils/guidanceGenerator.ts
function generateFullGuidanceContent(repoPath) {
  const config = getRepositoryConfiguration(repoPath);
  const guidance = getRepositoryGuidance(repoPath);
  const allowedTags = getAllowedTags(repoPath);
  const tagDescriptions = getTagDescriptions(repoPath);
  const allowedTypes = getAllowedTypes(repoPath);
  const typeDescriptions = getTypeDescriptions(repoPath);
  const output = ["# Repository Note Configuration\n"];
  output.push("## Configuration Limits");
  output.push(`- Max note length: ${config.limits.noteMaxLength} characters`);
  output.push(`- Max tags per note: ${config.limits.maxTagsPerNote}`);
  output.push(`- Max tag description length: ${config.limits.tagDescriptionMaxLength} characters`);
  output.push(`- Max anchors per note: ${config.limits.maxAnchorsPerNote}`);
  output.push("");
  output.push("## Tag Restrictions");
  if (allowedTags.enforced && allowedTags.tags.length > 0) {
    output.push("**Status:** ENFORCED");
    output.push(`**Allowed tags (${allowedTags.tags.length}):**`);
    for (const tag of allowedTags.tags) {
      const desc = tagDescriptions[tag];
      if (desc) {
        output.push(`- **${tag}**: ${desc}`);
      } else {
        output.push(`- **${tag}**`);
      }
    }
  } else {
    output.push("**Status:** NOT ENFORCED");
    output.push("Any tags can be used for notes.");
    if (Object.keys(tagDescriptions).length > 0) {
      output.push("\n**Available tag descriptions:**");
      for (const [tag, desc] of Object.entries(tagDescriptions)) {
        output.push(`- **${tag}**: ${desc}`);
      }
    }
  }
  output.push("");
  output.push("## Type Restrictions");
  if (allowedTypes.enforced && allowedTypes.types.length > 0) {
    output.push("**Status:** ENFORCED");
    output.push(`**Allowed types (${allowedTypes.types.length}):**`);
    for (const type of allowedTypes.types) {
      const desc = typeDescriptions[type];
      if (desc) {
        const firstLine = desc.split("\n")[0].replace(/^#\s*/, "");
        output.push(`- **${type}**: ${firstLine}`);
      } else {
        output.push(`- **${type}**`);
      }
    }
  } else {
    output.push("**Status:** NOT ENFORCED");
    output.push("Any types can be used for notes.");
    if (Object.keys(typeDescriptions).length > 0) {
      output.push("\n**Available type descriptions:**");
      for (const [type, desc] of Object.entries(typeDescriptions)) {
        const firstLine = desc.split("\n")[0].replace(/^#\s*/, "");
        output.push(`- **${type}**: ${firstLine}`);
      }
    }
  }
  output.push("");
  output.push("## Note Guidance");
  if (guidance) {
    output.push(guidance);
  } else {
    output.push("No repository-specific guidance found.");
    output.push(
      "Consider creating a `note-guidance.md` file in your `.a24z` directory to help team members understand what types of notes are most valuable for this project."
    );
  }
  output.push("");
  output.push("## Summary");
  output.push("### Files Location");
  output.push("- Configuration: `.a24z/configuration.json`");
  output.push("- Tag descriptions: `.a24z/tags/` (individual markdown files)");
  output.push("- Type descriptions: `.a24z/types/` (individual markdown files)");
  output.push("- Note guidance: `.a24z/note-guidance.md`");
  output.push("- Notes storage: `.a24z/notes/` (organized by year/month)");
  return output.join("\n");
}

// src/core-mcp/services/guidance-token-manager.ts
var GuidanceTokenManager = class {
  secret;
  constructor(secret) {
    this.secret = secret || DEFAULT_SECURITY_CONFIG.guidanceTokenSecret;
  }
  /**
   * Generate a token for guidance content
   * @param guidanceContent The guidance content
   * @param path The path context for the guidance
   * @returns Base64 encoded token
   */
  generateToken(guidanceContent, path19) {
    const payload = {
      guidanceHash: crypto.createHash("md5").update(guidanceContent).digest("hex"),
      path: path19,
      timestamp: Date.now(),
      expires: Date.now() + 24 * 60 * 60 * 1e3
      // 24 hours
    };
    const signature = crypto.createHmac("sha256", this.secret).update(JSON.stringify(payload)).digest("hex");
    const tokenData = { payload, signature };
    return Buffer.from(JSON.stringify(tokenData)).toString("base64");
  }
  /**
   * Validate a token against guidance content
   * @param token The token to validate
   * @param guidanceContent The current guidance content
   * @returns Whether the token is valid
   */
  validateToken(token, guidanceContent) {
    try {
      const tokenData = JSON.parse(Buffer.from(token, "base64").toString());
      const { payload, signature } = tokenData;
      const expectedSignature = crypto.createHmac("sha256", this.secret).update(JSON.stringify(payload)).digest("hex");
      if (signature !== expectedSignature) {
        return false;
      }
      if (Date.now() > payload.expires) {
        return false;
      }
      const currentHash = crypto.createHash("md5").update(guidanceContent).digest("hex");
      return payload.guidanceHash === currentHash;
    } catch {
      return false;
    }
  }
  /**
   * Parse a token to extract its payload (for debugging/inspection)
   * @param token The token to parse
   * @returns The token payload or null if invalid
   */
  parseToken(token) {
    try {
      const tokenData = JSON.parse(Buffer.from(token, "base64").toString());
      return tokenData.payload;
    } catch {
      return null;
    }
  }
  /**
   * Check if a token is expired without validating content
   * @param token The token to check
   * @returns Whether the token is expired
   */
  isTokenExpired(token) {
    const payload = this.parseToken(token);
    if (!payload) return true;
    return Date.now() > payload.expires;
  }
  /**
   * Validate a token for a specific repository path
   * Validates the token against the full guidance content
   * @param token The token to validate
   * @param repoOrFilePath The repository or file path
   * @returns Whether the token is valid
   * @throws Error if token is invalid
   */
  validateTokenForPath(token, repoOrFilePath) {
    if (!token) {
      throw new Error("Guidance token required. Please run get_repository_guidance first.");
    }
    const repoPath = normalizeRepositoryPath(repoOrFilePath);
    let guidanceContent = "";
    try {
      guidanceContent = generateFullGuidanceContent(repoPath);
    } catch {
      throw new Error(
        "Unable to generate guidance content. Please run get_repository_guidance first."
      );
    }
    if (!this.validateToken(token, guidanceContent)) {
      throw new Error(
        "Invalid or expired guidance token. Please run get_repository_guidance again."
      );
    }
  }
};

