// src/core-mcp/tools/GetRepositoryTagsTool.ts
import { z as z5 } from "zod";
var GetRepositoryTagsTool = class extends BaseTool {
  name = "get_repository_tags";
  description = "Get available tags for categorizing notes in a repository path, including repository-specific guidance";
  tokenManager;
  constructor() {
    super();
    this.tokenManager = new GuidanceTokenManager();
  }
  schema = z5.object({
    path: z5.string().describe(
      "The file or directory path to get tags for. Can be any path within the repository - the tool will find the repository root and analyze notes."
    ),
    includeUsedTags: z5.boolean().optional().default(true).describe(
      "Include tags that have been used in existing notes for this repository. Helps maintain consistency with established tagging patterns."
    ),
    includeSuggestedTags: z5.boolean().optional().default(true).describe(
      'Include AI-suggested tags based on the file path. For example, paths containing "auth" will suggest "authentication" tag.'
    ),
    includeGuidance: z5.boolean().optional().default(true).describe(
      "Include repository-specific note guidance. Shows either custom guidance from .a24z/note-guidance.md or falls back to default guidance."
    ),
    guidanceToken: z5.string().describe(
      "The guidance token obtained from get_repository_guidance. Required to ensure guidance has been read."
    )
  });
  async execute(input) {
    this.tokenManager.validateTokenForPath(input.guidanceToken, input.path);
    const result = { success: true, path: input.path };
    const tagDescriptions = getTagDescriptions(input.path);
    const allowedTagsInfo = getAllowedTags(input.path);
    if (allowedTagsInfo.enforced && allowedTagsInfo.tags.length > 0) {
      const allowedTagsWithDescriptions = allowedTagsInfo.tags.map((tagName) => ({
        name: tagName,
        description: tagDescriptions[tagName]
      }));
      result.tagRestrictions = {
        enforced: true,
        allowedTags: allowedTagsWithDescriptions,
        message: "This repository enforces tag restrictions. Only the allowed tags listed above can be used for notes."
      };
    } else {
      result.tagRestrictions = {
        enforced: false,
        message: "This repository does not enforce tag restrictions. Any tags can be used."
      };
    }
    if (input.includeUsedTags !== false) {
      const usedTags = getUsedTagsForPath(input.path);
      result.usedTags = usedTags.map((tagName) => ({
        name: tagName,
        description: tagDescriptions[tagName]
      }));
    }
    if (input.includeSuggestedTags !== false) {
      const suggestedTags = getSuggestedTagsForPath(input.path);
      result.suggestedTags = suggestedTags.map((suggestion) => ({
        ...suggestion,
        description: tagDescriptions[suggestion.name]
      }));
    }
    if (input.includeGuidance !== false) {
      const guidance = getRepositoryGuidance(input.path);
      if (guidance) {
        result.repositoryGuidance = guidance;
      } else {
        result.guidanceNote = "No repository-specific guidance found. Consider creating a note-guidance.md file in your .a24z directory to help team members understand what types of notes are most valuable for this project.";
      }
    }
    return { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] };
  }
};

// src/core-mcp/tools/GetRepositoryTypesTool.ts
import { z as z6 } from "zod";
var GetRepositoryTypesTool = class extends BaseTool {
  name = "get_repository_types";
  description = "Get available note types for categorizing notes in a repository path, including repository-specific guidance";
  tokenManager;
  constructor() {
    super();
    this.tokenManager = new GuidanceTokenManager();
  }
  schema = z6.object({
    path: z6.string().describe(
      "The file or directory path to get types for. Can be any path within the repository - the tool will find the repository root and analyze note types."
    ),
    includeGuidance: z6.boolean().optional().describe(
      "Include repository-specific note guidance. Shows either custom guidance from .a24z/note-guidance.md or falls back to default guidance."
    ),
    guidanceToken: z6.string().describe(
      "The guidance token obtained from get_repository_guidance. Required to ensure guidance has been read."
    )
  });
  async execute(input) {
    this.tokenManager.validateTokenForPath(input.guidanceToken, input.path);
    const result = { success: true, path: input.path };
    const typeDescriptions = getTypeDescriptions(input.path);
    const allowedTypesInfo = getAllowedTypes(input.path);
    if (allowedTypesInfo.enforced && allowedTypesInfo.types.length > 0) {
      const allowedTypesWithDescriptions = allowedTypesInfo.types.map((typeName) => ({
        name: typeName,
        description: typeDescriptions[typeName]
      }));
      result.typeRestrictions = {
        enforced: true,
        allowedTypes: allowedTypesWithDescriptions,
        message: "This repository enforces type restrictions. Only the allowed types listed above can be used for notes."
      };
    } else {
      result.typeRestrictions = {
        enforced: false,
        message: "This repository does not enforce type restrictions. Any types can be used."
      };
      if (Object.keys(typeDescriptions).length > 0) {
        const availableTypes = Object.entries(typeDescriptions).map(([name, description]) => ({
          name,
          description
        }));
        result.availableTypes = availableTypes;
      }
    }
    const commonTypes = [
      {
        name: "explanation",
        description: "Explains how something works or why it was implemented in a particular way"
      },
      {
        name: "decision",
        description: "Documents architectural decisions, trade-offs, or important choices made"
      },
      {
        name: "pattern",
        description: "Describes reusable patterns, conventions, or best practices in the codebase"
      },
      {
        name: "gotcha",
        description: "Warns about potential pitfalls, edge cases, or things that are easy to get wrong"
      }
    ];
    result.commonTypes = commonTypes;
    if (input.includeGuidance !== false) {
      const guidance = getRepositoryGuidance(input.path);
      if (guidance) {
        result.repositoryGuidance = guidance;
      } else {
        result.guidanceNote = "No repository-specific guidance found. Consider creating a note-guidance.md file in your .a24z directory to help team members understand what types of notes are most valuable for this project.";
      }
    }
    return { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] };
  }
};

// src/core-mcp/tools/GetRepositoryGuidanceTool.ts
import { z as z7 } from "zod";
var GetRepositoryGuidanceTool = class extends BaseTool {
  name = "get_repository_guidance";
  description = "Get comprehensive repository configuration including note guidance, tag restrictions, and tag descriptions";
  tokenManager;
  constructor() {
    super();
    this.tokenManager = new GuidanceTokenManager();
  }
  schema = z7.object({
    path: z7.string().describe(
      "The file or directory path to get guidance for. Can be any path within the repository - the tool will find the repository root and provide comprehensive configuration."
    ),
    includeToken: z7.boolean().optional().describe("Whether to include a guidance token for note validation (default: true)")
  });
  async execute(input) {
    const fullContent = generateFullGuidanceContent(input.path);
    const output = fullContent.split("\n");
    const includeToken = input.includeToken !== false;
    let token;
    if (includeToken) {
      token = this.tokenManager.generateToken(fullContent, input.path);
      output.push("");
      output.push("## Guidance Token");
      output.push("This token proves you have read the current guidance:");
      output.push(`\`${token}\``);
      output.push("");
      output.push("Include this token when creating notes to verify guidance compliance.");
      output.push("Token expires in 24 hours.");
    }
    const result = {
      content: [
        {
          type: "text",
          text: output.join("\n")
        }
      ]
    };
    if (token) {
      result.guidanceToken = token;
    }
    return result;
  }
};

