// src/core-mcp/tools/GetNoteByIdTool.ts
import { z as z9 } from "zod";
import * as path7 from "node:path";
import * as fs5 from "node:fs";
init_pathNormalization();
var GetNoteByIdTool = class extends BaseTool {
  name = "get_repository_note";
  description = "Get a repository note by its unique ID";
  schema = z9.object({
    noteId: z9.string().describe('The unique ID of the note to retrieve (e.g., "note-1734567890123-abc123def")'),
    directoryPath: z9.string().describe(
      "The absolute path to the git repository root directory or any path within it. The tool will find the repository root automatically."
    )
  });
  async execute(input) {
    const parsed = this.schema.parse(input);
    if (!path7.isAbsolute(parsed.directoryPath)) {
      throw new Error(
        `directoryPath must be an absolute path. Received relative path: "${parsed.directoryPath}". Please provide the full absolute path (e.g., /Users/username/projects/my-repo).`
      );
    }
    if (!fs5.existsSync(parsed.directoryPath)) {
      throw new Error(
        `directoryPath does not exist: "${parsed.directoryPath}". Please provide a valid absolute path to an existing directory.`
      );
    }
    const gitRoot = findGitRoot(parsed.directoryPath);
    if (!gitRoot) {
      throw new Error(
        `directoryPath is not within a git repository: "${parsed.directoryPath}". Please provide a path within a git repository.`
      );
    }
    const note = getNoteById(gitRoot, parsed.noteId);
    if (!note) {
      throw new Error(
        `Note with ID "${parsed.noteId}" not found in repository "${gitRoot}". Please verify the note ID is correct.`
      );
    }
    const output = [
      `# Note ID: ${note.id}`,
      "",
      `**Type:** ${note.type}`,
      `**Tags:** ${note.tags.join(", ")}`,
      `**Created:** ${new Date(note.timestamp).toISOString()}`,
      "",
      "## Anchors",
      ...note.anchors.map((anchor) => `- ${anchor}`),
      "",
      "## Content",
      note.note
    ];
    if (note.metadata && Object.keys(note.metadata).length > 0) {
      output.push("", "## Metadata");
      for (const [key, value] of Object.entries(note.metadata)) {
        output.push(`- **${key}:** ${JSON.stringify(value)}`);
      }
    }
    return {
      content: [
        {
          type: "text",
          text: output.join("\n")
        }
      ]
    };
  }
};

