// src/core-mcp/tools/CreateHandoffBriefTool.ts
import { z as z11 } from "zod";

// src/core-mcp/store/handoffStore.ts
init_pathNormalization();
import * as fs7 from "fs";
import * as path9 from "path";
function generateHandoffId() {
  const chars = "abcdefghijklmnopqrstuvwxyz0123456789";
  let result = "";
  for (let i = 0; i < 8; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
}
function getHandoffsDir(repositoryPath) {
  const normalizedPath = normalizeRepositoryPath(repositoryPath);
  return path9.join(normalizedPath, ".a24z", "handoffs");
}
function formatHandoffAsMarkdown(params) {
  const lines = [
    `# ${params.title}`,
    "",
    "## Overview",
    params.overview,
    "",
    "## Code & Context",
    ""
  ];
  for (const ref of params.references) {
    lines.push(`\`${ref.anchor}\``);
    lines.push(`- ${ref.context}`);
    lines.push("");
  }
  return lines.join("\n");
}
function saveHandoffBrief(params) {
  const timestamp = Date.now();
  const id = generateHandoffId();
  const handoffId = `handoff-${timestamp}-${id}`;
  const date = new Date(timestamp);
  const year = date.getFullYear().toString();
  const month = (date.getMonth() + 1).toString().padStart(2, "0");
  const handoffsDir = getHandoffsDir(params.directoryPath);
  const yearMonthDir = path9.join(handoffsDir, year, month);
  fs7.mkdirSync(yearMonthDir, { recursive: true });
  const filename = `${handoffId}.md`;
  const filepath = path9.join(yearMonthDir, filename);
  const content = formatHandoffAsMarkdown(params);
  fs7.writeFileSync(filepath, content, "utf8");
  return {
    id: handoffId,
    timestamp,
    filepath
  };
}
function getHandoffBriefs(repositoryPath, options) {
  const handoffsDir = getHandoffsDir(repositoryPath);
  const allBriefs = [];
  if (!fs7.existsSync(handoffsDir)) {
    return allBriefs;
  }
  const years = fs7.readdirSync(handoffsDir).filter((y) => fs7.statSync(path9.join(handoffsDir, y)).isDirectory());
  for (const year of years) {
    const yearDir = path9.join(handoffsDir, year);
    const months = fs7.readdirSync(yearDir).filter((m) => fs7.statSync(path9.join(yearDir, m)).isDirectory());
    for (const month of months) {
      const monthDir = path9.join(yearDir, month);
      const files = fs7.readdirSync(monthDir).filter((f) => f.endsWith(".md"));
      for (const file of files) {
        const match = file.match(/handoff-(\d+)-([a-z0-9]+)\.md/);
        if (!match) continue;
        const timestamp = parseInt(match[1], 10);
        const id = `handoff-${match[1]}-${match[2]}`;
        if (options?.since && timestamp < options.since) continue;
        const filepath = path9.join(monthDir, file);
        allBriefs.push({
          id,
          timestamp,
          filepath
        });
      }
    }
  }
  allBriefs.sort((a, b) => {
    if (b.timestamp !== a.timestamp) {
      return b.timestamp - a.timestamp;
    }
    return b.id.localeCompare(a.id);
  });
  if (options?.limit && allBriefs.length > options.limit) {
    return allBriefs.slice(0, options.limit);
  }
  return allBriefs;
}
function getHandoffBriefsWithTitles(repositoryPath, options) {
  const briefs = getHandoffBriefs(repositoryPath, options);
  const results = [];
  for (const brief of briefs) {
    try {
      const content = fs7.readFileSync(brief.filepath, "utf8");
      const titleMatch = content.match(/^#\s+(.+)$/m);
      const title = titleMatch ? titleMatch[1] : "Untitled Handoff";
      results.push({
        ...brief,
        title
      });
    } catch {
      results.push({
        ...brief,
        title: `Handoff ${brief.id}`
      });
    }
  }
  return results;
}

// src/core-mcp/tools/CreateHandoffBriefTool.ts
var CreateHandoffBriefTool = class extends BaseTool {
  name = "create_handoff_brief";
  description = "Create a handoff brief with overview and code references for knowledge transfer";
  schema = z11.object({
    title: z11.string().describe("The title of the handoff brief"),
    overview: z11.string().describe("Overview section explaining the context and current state"),
    references: z11.array(
      z11.object({
        anchor: z11.string().describe("File or directory path to reference"),
        context: z11.string().describe("Context or notes about this code location")
      })
    ).describe("Code references with context"),
    directoryPath: z11.string().describe("The directory path where the handoff should be created (repository root)"),
    ephemeral: z11.boolean().optional().default(false).describe("If true, the handoff will be deleted after being read once")
  });
  async execute(input) {
    try {
      let overview = input.overview;
      if (input.ephemeral) {
        overview = `[EPHEMERAL: This handoff will be deleted after reading]

${overview}`;
      }
      const handoff = saveHandoffBrief({
        title: input.title,
        overview,
        references: input.references,
        directoryPath: input.directoryPath
      });
      const ephemeralNote = input.ephemeral ? "\n\n\u26A0\uFE0F This is an EPHEMERAL handoff - it will be deleted after being read once." : "";
      return {
        content: [
          {
            type: "text",
            text: `\u2705 Handoff brief created successfully!

ID: ${handoff.id}
Location: ${handoff.filepath}
Timestamp: ${new Date(handoff.timestamp).toISOString()}${ephemeralNote}

The handoff brief has been saved and can be shared with team members for knowledge transfer.`
          }
        ]
      };
    } catch (error) {
      return {
        content: [
          {
            type: "text",
            text: `\u274C Failed to create handoff brief: ${error instanceof Error ? error.message : "Unknown error"}`
          }
        ],
        isError: true
      };
    }
  }
};

// src/core-mcp/tools/ListHandoffBriefsTool.ts
import { z as z12 } from "zod";
init_pathNormalization();
var ListHandoffBriefsTool = class extends BaseTool {
  name = "list_handoff_briefs";
  description = "List all handoff briefs with their titles for a repository";
  schema = z12.object({
    directoryPath: z12.string().describe("The absolute path to the git repository root directory or any path within it"),
    limit: z12.number().optional().describe("Maximum number of briefs to return (optional)"),
    since: z12.number().optional().describe("Only return briefs created after this timestamp (optional)")
  });
  async execute(input) {
    try {
      const repositoryRoot = findGitRoot(input.directoryPath);
      if (!repositoryRoot) {
        return {
          content: [
            {
              type: "text",
              text: "\u274C **Error:** The specified path is not within a git repository."
            }
          ],
          isError: true
        };
      }
      const briefs = getHandoffBriefsWithTitles(repositoryRoot, {
        limit: input.limit,
        since: input.since
      });
      if (briefs.length === 0) {
        return {
          content: [
            {
              type: "text",
              text: "\u{1F4CB} **No handoff briefs found**\n\nNo handoff briefs have been created for this repository yet."
            }
          ]
        };
      }
      const lines = [
        `\u{1F4CB} **Handoff Briefs for Repository**`,
        `\u{1F4C1} Repository: ${repositoryRoot}`,
        `\u{1F4CA} Found ${briefs.length} handoff brief${briefs.length === 1 ? "" : "s"}`,
        ""
      ];
      for (const brief of briefs) {
        const date = new Date(brief.timestamp);
        const formattedDate = date.toLocaleString("en-US", {
          year: "numeric",
          month: "short",
          day: "numeric",
          hour: "2-digit",
          minute: "2-digit"
        });
        lines.push(`### ${brief.title}`);
        lines.push(`- **ID:** \`${brief.id}\``);
        lines.push(`- **Created:** ${formattedDate}`);
        lines.push(`- **Path:** \`${brief.filepath}\``);
        lines.push("");
      }
      if (input.limit && briefs.length === input.limit) {
        lines.push(
          `*Note: Results limited to ${input.limit} briefs. There may be more available.*`
        );
      }
      return {
        content: [
          {
            type: "text",
            text: lines.join("\n")
          }
        ]
      };
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      return {
        content: [
          {
            type: "text",
            text: `\u274C **Error listing handoff briefs:** ${errorMessage}`
          }
        ],
        isError: true
      };
    }
  }
};

// src/core-mcp/tools/GetStaleNotesTool.ts
import { z as z13 } from "zod";
init_pathNormalization();
import path10 from "path";
import { existsSync as existsSync8 } from "fs";
var GetStaleNotesSchema = z13.object({
  directoryPath: z13.string().describe(
    "The absolute path to the git repository root directory or any path within it. The tool will find the repository root automatically."
  ),
  includeContent: z13.boolean().default(true).describe(
    "Whether to include the full note content in the response. Set to false for a more compact output."
  ),
  includeValidAnchors: z13.boolean().default(false).describe(
    "Whether to include the list of valid anchors (files that still exist) for each note."
  )
});
var GetStaleNotesTool = class extends BaseTool {
  name = "get_stale_notes";
  description = "Get all notes that have stale anchors (references to files that no longer exist) in a repository";
  schema = GetStaleNotesSchema;
  async execute(input) {
    const parsed = this.schema.parse(input);
    const { directoryPath, includeContent, includeValidAnchors } = parsed;
    const normalizedPath = path10.resolve(directoryPath);
    if (!existsSync8(normalizedPath)) {
      throw new Error(`Path does not exist: ${normalizedPath}`);
    }
    const repoRoot = findGitRoot(normalizedPath);
    if (!repoRoot) {
      throw new Error(
        `Not a git repository: ${normalizedPath}. This tool requires a git repository.`
      );
    }
    const staleNotes = checkStaleNotes(repoRoot);
    if (staleNotes.length === 0) {
      return {
        content: [
          {
            type: "text",
            text: `No notes with stale anchors found in repository: ${repoRoot}`
          }
        ]
      };
    }
    const formattedNotes = staleNotes.map((staleNote) => {
      const formatted = {
        noteId: staleNote.note.id,
        type: staleNote.note.type || "note",
        tags: staleNote.note.tags,
        staleAnchors: staleNote.staleAnchors,
        timestamp: staleNote.note.timestamp
      };
      if (includeValidAnchors) {
        formatted.validAnchors = staleNote.validAnchors;
      }
      if (includeContent) {
        formatted.content = staleNote.note.note;
      }
      if (staleNote.note.metadata && Object.keys(staleNote.note.metadata).length > 0) {
        formatted.metadata = staleNote.note.metadata;
      }
      return formatted;
    });
    formattedNotes.sort((a, b) => b.timestamp - a.timestamp);
    const totalStaleAnchors = staleNotes.reduce((sum, note) => sum + note.staleAnchors.length, 0);
    const totalValidAnchors = staleNotes.reduce((sum, note) => sum + note.validAnchors.length, 0);
    const response = {
      repository: repoRoot,
      totalStaleNotes: staleNotes.length,
      totalStaleAnchors,
      totalValidAnchors,
      notes: formattedNotes,
      recommendation: "Consider updating or removing these notes as their referenced files no longer exist. Use delete_repository_note to remove them or update their anchors to point to existing files."
    };
    return {
      content: [
        {
          type: "text",
          text: JSON.stringify(response, null, 2)
        }
      ]
    };
  }
};

