init_pathNormalization();
import * as fs10 from "node:fs";
import * as path16 from "node:path";
function checkQuestConfiguration(repositoryPath, requestedQuest) {
  const repoPath = normalizeRepositoryPath(repositoryPath);
  const configPath = path16.join(repoPath, ".a24z", "documentation-quests.json");
  const status = {
    hasConfiguration: false,
    configPath,
    availableQuests: [],
    hasRequestedQuest: false,
    requestedQuest
  };
  if (!fs10.existsSync(configPath)) {
    return status;
  }
  try {
    const content = fs10.readFileSync(configPath, "utf8");
    const instructions = JSON.parse(content);
    for (const [questType, questInstructions] of Object.entries(instructions)) {
      if (questType.startsWith("_")) continue;
      if (Array.isArray(questInstructions) && questInstructions.length > 0) {
        status.availableQuests.push(questType);
      }
    }
    status.hasConfiguration = status.availableQuests.length > 0;
    if (requestedQuest) {
      status.hasRequestedQuest = status.availableQuests.includes(requestedQuest);
    }
  } catch (error) {
    console.error("Error loading quest configuration:", error);
  }
  return status;
}
function loadQuestInstructions(repositoryPath) {
  const repoPath = normalizeRepositoryPath(repositoryPath);
  const instructionsPath = path16.join(repoPath, ".a24z", "documentation-quests.json");
  try {
    if (fs10.existsSync(instructionsPath)) {
      const content = fs10.readFileSync(instructionsPath, "utf8");
      const instructions = JSON.parse(content);
      const validInstructions = {};
      for (const [questType, questInstructions] of Object.entries(instructions)) {
        if (!questType.startsWith("_") && Array.isArray(questInstructions) && questInstructions.length > 0) {
          validInstructions[questType] = questInstructions;
        }
      }
      return Object.keys(validInstructions).length > 0 ? validInstructions : null;
    }
  } catch (error) {
    console.error("Error loading quest instructions:", error);
  }
  return null;
}
function getRandomQuestInstruction(instructions, questType) {
  const options = instructions[questType];
  if (!options || options.length === 0) {
    return null;
  }
  return options[Math.floor(Math.random() * options.length)];
}

